<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {Play,Square,ArrowUpRight} from 'lucide-vue-next';import {api,post,type RunConfig,type Run,type RunReport} from '../api';import {usePoll,useSimulator} from '../composables/poll';import {useAuth} from '../stores/auth';import {time} from '../money';import DataState from '../components/DataState.vue';import StatusBadge from '../components/StatusBadge.vue';
const auth=useAuth();const presets=ref<RunConfig[]>([]);const selected=ref<string>('');const cfg=ref<RunConfig>({preset:'Normal',targetRps:5,durationSeconds:10,concurrency:20,randomSeed:42,duplicatePercent:0,invalidSignaturePercent:0,bankFailedPercent:0,unknownReferencePercent:0,missingPercent:0,loanReference:null,amountMinor:'900000'});const busy=ref(false);const actionError=ref('');
const application=usePoll(signal=>selected.value?api<{processedUnique:number;appliedUnique:number;creditReview:number;unmatched:number;bankDeclined:number;refreshedAt:string}>('/run-application/'+selected.value,{signal}):Promise.resolve(null));watch(selected,()=>application.refresh());const runs=usePoll(signal=>api<Run[]>('/runs',{signal}));const path=computed(()=>selected.value?'/runs/'+selected.value:'/runs');const report=useSimulator<RunReport|Run[]>(path);const result=computed(()=>Array.isArray(report.data.value)?undefined:report.data.value);
void api<RunConfig[]>('/presets').then(p=>presets.value=p).catch(e=>actionError.value=String(e));watch(runs.data,r=>{if(r?.length&&!selected.value)selected.value=r[0].id});
async function start(){busy.value=true;actionError.value='';try{const run=await post<{id:string}>('/runs',cfg.value);selected.value=run.id;await runs.refresh()}catch(e){actionError.value=e instanceof Error?e.message:'Start failed'}finally{busy.value=false}}
async function stop(){busy.value=true;try{await post('/runs/'+selected.value+'/stop');await runs.refresh();await report.refresh()}catch(e){actionError.value=e instanceof Error?e.message:'Stop failed'}finally{busy.value=false}}
</script>
<template><div class="page-title"><div><p class="eyebrow">EXTERNAL BANK · CONTROLLED LOAD</p><h1>Bank simulator</h1><p class="muted">Plan unique transactions, sign deliveries, and observe achieved throughput.</p></div><span class="badge warn">BUSINESS DATE · 31 OCT 2026</span></div><DataState :loading="runs.loading.value" :error="runs.error.value" :updated-at="runs.updatedAt.value"/><el-alert v-if="actionError" :title="actionError" type="error" :closable="false"/>
<div class="preset-grid"><button v-for="preset in presets" :key="preset.preset" class="preset-card" :class="{chosen:cfg.preset===preset.preset}" @click="cfg={...preset}"><strong>{{preset.preset}}</strong><span>{{preset.targetRps}} RPS · {{preset.durationSeconds}}s · {{preset.concurrency}} in flight</span><ArrowUpRight :size="16"/></button></div>
<section class="panel"><div class="panel-heading"><div><h3>Configure a run</h3><p>Target load is configurable; achieved throughput depends on this machine.</p></div><span class="count-pill">{{auth.role}} access</span></div><el-form label-position="top" :disabled="auth.role!=='Admin'||busy"><div class="form-grid"><el-form-item label="Target requests / second"><el-input-number v-model="cfg.targetRps" :min="1" :max="500"/></el-form-item><el-form-item label="Duration (seconds)"><el-input-number v-model="cfg.durationSeconds" :min="1" :max="600"/></el-form-item><el-form-item label="Concurrency cap"><el-input-number v-model="cfg.concurrency" :min="1" :max="200"/></el-form-item><el-form-item label="Random seed"><el-input-number v-model="cfg.randomSeed"/></el-form-item><el-form-item label="Duplicate deliveries (%)"><el-input-number v-model="cfg.duplicatePercent" :min="0" :max="100"/></el-form-item><el-form-item label="Invalid signatures (%)"><el-input-number v-model="cfg.invalidSignaturePercent" :min="0" :max="100"/></el-form-item><el-form-item label="Bank failures (%)"><el-input-number v-model="cfg.bankFailedPercent" :min="0" :max="100"/></el-form-item><el-form-item label="Unknown references (%)"><el-input-number v-model="cfg.unknownReferencePercent" :min="0" :max="100"/></el-form-item><el-form-item label="Missing delivery (%)"><el-input-number v-model="cfg.missingPercent" :min="0" :max="100"/></el-form-item><el-form-item label="Fixed loan (optional)"><el-input v-model="cfg.loanReference" placeholder="Round-robin across 1,000 loans" clearable/></el-form-item><el-form-item label="Payment amount (integer satang)"><el-input v-model="cfg.amountMinor"/></el-form-item></div><el-button type="primary" :loading="busy" @click="start"><Play :size="15"/> Start simulation</el-button><el-button :disabled="result?.run.status!=='Running'" @click="stop"><Square :size="15"/>Stop active run</el-button></el-form><p v-if="auth.role==='Observer'" class="chart-note">Observer sessions can view runs. Admin authorization is enforced on the server.</p></section>
<section class="panel"><div class="panel-heading"><h3>Run results</h3><el-select v-model="selected" placeholder="Select a recorded run" class="search"><el-option v-for="r in runs.data.value??[]" :key="r.id" :value="r.id" :label="r.preset+' · '+time(r.createdAt)"/></el-select></div><template v-if="result"><StatusBadge :status="result.run.status"/><DataState :loading="report.loading.value" :error="report.error.value" :updated-at="report.updatedAt.value"/><div class="result-grid"><div><span>Intended unique payments</span><strong>{{result.run.plannedUnique}}</strong></div><div><span>Attempted deliveries</span><strong>{{result.attemptedDeliveries}}</strong></div><div><span>Achieved send rate</span><strong>{{result.achievedRps.toFixed(1)}} <small>RPS</small></strong></div><div><span>Accepted receipts</span><strong>{{result.acceptedReceipts}}</strong></div><div><span>Planned duplicate copies</span><strong>{{result.duplicateCopies}}</strong></div><div><span>Skipped / rejected / timed out</span><strong>{{result.skipped}} / {{result.rejected}} / {{result.timeouts}}</strong></div></div><div class="result-grid"><div><span>Applied unique transactions</span><strong>{{application.data.value?.appliedUnique??'Unavailable'}}</strong></div><div><span>Applied with credit review</span><strong>{{application.data.value?.creditReview??'Unavailable'}}</strong></div><div><span>Unmatched / bank declined</span><strong>{{application.data.value?application.data.value.unmatched+' / '+application.data.value.bankDeclined:'Unavailable'}}</strong></div></div><DataState :loading="application.loading.value" :error="application.error.value" :updated-at="application.updatedAt.value"/><p class="chart-note">Application counts: unique LoanService processing records. Receipt acceptance and completed allocation are separate.</p><el-alert v-if="result.maxSchedulingLagMs>1000" title="Backpressure detected: scheduling lag exceeds one second" :description="'Maximum lag: '+result.maxSchedulingLagMs.toFixed(0)+' ms. CPU or concurrency limits may constrain target load.'" type="warning" :closable="false"/><p>Maximum observed scheduling lag: {{result.maxSchedulingLagMs.toFixed(0)}} ms.</p><RouterLink :to="'/reconciliation?run='+selected" class="text-link">Compare completed allocations against bank settlement ↗</RouterLink><el-table :data="result.recentAttempts"><el-table-column prop="bankTransactionId" label="Bank transaction" min-width="300"/><el-table-column label="Sent"><template #default="{row}">{{time(row.startedAt)}}</template></el-table-column><el-table-column prop="responseCode" label="HTTP response"/><el-table-column label="Latency"><template #default="{row}">{{row.durationMs.toFixed(0)}} ms</template></el-table-column></el-table></template><el-empty v-else description="No simulator run selected. Counters appear after a persisted run exists."/></section>
<section class="panel"><div class="panel-heading"><h3>Run history & preset comparison</h3></div><el-table :data="runs.data.value??[]" class="clickable-table" @row-click="(row:Run)=>selected=row.id"><el-table-column prop="preset" label="Preset"/><el-table-column prop="plannedUnique" label="Unique payments"/><el-table-column label="Started"><template #default="{row}">{{time(row.createdAt)}}</template></el-table-column><el-table-column label="Maximum scheduling lag"><template #default="{row}">{{row.maximumLagMs.toFixed(0)}} ms</template></el-table-column><el-table-column label="State"><template #default="{row}"><StatusBadge :status="row.status"/></template></el-table-column></el-table></section></template>

